/*
 * A108201  Numbers of the form (5^i)*(12^j), with i, j >= 0.
 * https://oeis.org/A108201
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = the nth smallest number of the form 5^i * 12^j (i, j >=
 *            0). The sequence is generated by merging two increasing
 *            sequences: {5^k * a[·]} and {12^k * a[·]} in the same way as in
 *            the classic “smooth numbers” algorithm
 * Range:     u8 n <= 6, u16 n <= 21, u32 n <= 73, u64 n <= 269,
 *            u128 n <= 1030, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <assert.h>

/* static state ----------------------------------------------------- */
static seq_t *seq     = NULL;   /* array of generated terms          */
static idx_t  seq_len = 0;      /* number of terms currently stored */
static idx_t  seq_cap = 0;      /* capacity of the array            */
static idx_t  idx5    = 0;      /* next index for factor 5          */
static idx_t  idx12   = 0;      /* next index for factor 12         */

/* ensure that at least `need` slots are available                */
static void ensure_capacity(idx_t need)
{
    if (seq_cap >= need)
        return;
    idx_t new_cap = seq_cap ? seq_cap * 2 : 16;
    if (new_cap < need)
        new_cap = need;
    /* cast `realloc` return value for portable C++ compilers   */
    seq_t *tmp = (seq_t *)realloc(seq, new_cap * sizeof(seq_t));
    if (!tmp)
        abort();               /* out of memory */
    seq = tmp;
    seq_cap = new_cap;
}

/* ---------------------------------------------------------------- */
seq_t a(idx_t n)
{
    if (n == 0)           /* undefined; return 0 for safety      */
        return (seq_t)0;

    /* initialise on first call                                   */
    if (seq_len == 0) {
        ensure_capacity(16);
        seq[0] = (seq_t)1; /* 5^0 * 12^0                            */
        seq_len = 1;
        idx5 = 0;
        idx12 = 0;
    }

    if (n > seq_cap)
        ensure_capacity(n);

    /* generate terms until we have at least `n` of them          */
    while (seq_len < n) {
        seq_t cand5  = seq[idx5] * (seq_t)5;
        seq_t cand12 = seq[idx12] * (seq_t)12;
        seq_t next   = (cand5 < cand12) ? cand5 : cand12;

        seq[seq_len++] = next;

        if (next == cand5)
            ++idx5;
        if (next == cand12)
            ++idx12;
    }

    return seq[n - 1];     /* indexes are 0‑based in the array          */
}
